import{_ as s,l as i,o as n,c as r,v as d,p as h,x as e,d as l,i as p,S as m,b as t}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"注意力长度缩放","description":"","frontmatter":{"title":"注意力长度缩放","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-length-scaling.md","filePath":"llm/attention-length-scaling.md","lastUpdated":1789023840000}'),c={name:"llm/attention-length-scaling.md"};function f(g,a,u,_,k,x){const o=i("Mermaid");return n(),r("div",null,[a[1]||(a[1]=d('<h1 id="注意力长度缩放" tabindex="-1">注意力长度缩放 <a class="header-anchor" href="#注意力长度缩放" aria-label="Permalink to &quot;注意力长度缩放&quot;">​</a></h1><div class="epigraph"><p>softmax 的锐度随键的个数变；只除 $\\sqrt{d_k}$ 时，序列一长，有效温度并没有按长度校准。</p><footer>—— Chiang &amp; Cholak, Overcoming a Theoretical Limitation of Self-Attention, ICLR 2022；长度外推中的缩放实践亦见 Press et al., Train Short, Test Long, ICLR 2022</footer></div><p><a href="/llm/head-dim-vs-heads">上一课</a>钉死了 \\(d_k\\) 进入温度的那一侧。<a href="/llm/sdpa">SDPA</a> 的另一侧——键的个数 \\(n\\)——没有进公式。短训长测时，同一套 logits 面对多得多的竞争者，权重被稀释或异常尖峰。本课补长度相关缩放：在 \\(\\sqrt{d_k}\\) 之外乘 \\(n\\) 的函数。后课谈头在做什么，默认你会「长序列先校准温度，再解释头」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>softmax 对向量 \\(z\\in\\mathbb{R}^{n}\\)，\\(n\\) 增大时即便 \\(z\\) 的典型幅度不变，最大值被选中的概率结构也会变：更多近乎无关的键分走正质量，或相反，极端值在更大的表里更容易独占。Chiang 与 Cholak 指出，某些形式语言任务需要权重以 \\(1/n\\) 量级平均分配，标准 \\(1/\\sqrt{d_k}\\) 做不到与长度无关的均匀。缺口是：<strong>打分尺度应随上下文长度改</strong>，否则层在 2k 上学到的峰度到 32k 上已经不是同一算子。</p><p><a href="/llm/sigmoid-attention">Sigmoid 注意力</a> 没有行和 1，更必须显式 \\(1/n\\)。Softmax 不是必须，但经验上 log-length 或 \\(\\sqrt{n}\\) 因子常能稳住外推。ALiBi 用距离偏置外推，不替代本课的全局温度；二者处理的是「谁更近」对「整体有多尖」。</p><p><span class="marginnote">推理时另设采样温度，作用在词表 logits 上，不是注意力内部温度。不要把两条温度收成一个旋钮。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把分数写成</p> \\[S=\\frac{QK^\\top}{\\sqrt{d_k}}\\, s(n), \\]<p>或等价地 \\(\\mathrm{softmax}(S/\\tau(n))\\)。常见 \\(s(n)\\)：常数 1（默认 SDPA）；\\(c/\\log n\\)；\\(\\sqrt{m/n}\\) 把训练长度 \\(m\\) 校准到测试长度 \\(n\\)；Chiang 式的 \\(1/n\\) 乘在权重侧而非 logits 侧。实现上 \\(n\\) 用有效长度（扣 padding），因果情形下每行的 \\(n\\) 其实是 \\(i\\)，严格做法是按行缩放，粗做法用全局 \\(n\\)。</p><p>训练若始终固定长度，模型会把 \\(s(n)\\) 吃进 \\(W^Q,W^K\\) 的尺度。要让 \\(s(n)\\) 在外推时起作用，训练就应变化长度，或把 \\(s(n)\\) 设计成在训练长度上约等于 1，只在偏离 \\(m\\) 时启动。</p><h3 id="与位置外推的分工" tabindex="-1">与位置外推的分工 <a class="header-anchor" href="#与位置外推的分工" aria-label="Permalink to &quot;与位置外推的分工&quot;">​</a></h3><p>RoPE 的波长、YaRN 的插值、ALiBi 的斜率，改的是哪些位置相容。长度缩放改的是 softmax 的锐度，即使位置编码已经外推成功，锐度不对仍会读错。先校准温度，再谈位置，是本课的顺序。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\tau\\) 变大，分布趋均匀，长上下文的噪声键稀释信号；\\(\\tau\\) 变小，分布趋 one-hot，长表上更容易只盯一个键、忽略其余证据。需要多证据融合的层偏好随 \\(n\\) 略增温；需要精确拷贝的头偏好保持尖。按层或按头设 \\(s(n)\\) 表达力更强，但几乎没人在生产里做到这么细，因为 KV 核与检查点都假定统一缩放。</p><p>按行用 \\(i\\) 缩放更符合因果：位置 3 只看见 3 个键，位置 3 万看见 3 万个。用全局 \\(n\\) 会让短前缀过尖或过平，属于实现偷懒。</p><p><span class="marginnote">层归一化会部分吸收尺度，但 LN 在注意力之后，进 softmax 的 logits 已经饱和过了。长度缩放必须发生在 softmax 之前。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有一种 \\(s(n)\\) 同时服务复制与平均。盲目 \\(1/n\\) 会把已训好的尖峰头打平。本课不取代相对偏置、RoPE、窗口。评测必须报训练长度与测试长度，否则「长上下文变好」可能只是温度碰巧合适。下一课用可视化与电路解释头，那些图都对温度敏感：换 \\(s(n)\\) 后「这个头在看什么」会变。</p>',20)),(n(),h(m,null,{default:e(()=>[p(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22QK%20%E9%99%A4%E6%A0%B9%E5%8F%B7%20d_k%22%5D%20--%3E%20SN%5B%22%E5%86%8D%E4%B9%98%20s(n)%20%E6%88%96%20tau(n)%22%5D%0A%20%20SN%20--%3E%20M%5B%22%E6%8E%A9%E7%A0%81%22%5D%0A%20%20M%20--%3E%20P%5B%22Softmax%22%5D%0A%20%20N%5B%22%E6%9C%89%E6%95%88%E9%95%BF%E5%BA%A6%20n%22%5D%20--%3E%20SN%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t("h2",{id:"小结",tabindex:"-1"},[l("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=t("ul",null,[t("li",null,"\\(\\sqrt{d_k}\\) 校准的是头维，不校准键的个数；长序列需要额外的 \\(s(n)\\) 或 \\(\\tau(n)\\)。"),t("li",null,"训练长度上 \\(s(n)\\approx 1\\)，偏离时才启动，才谈得上外推。"),t("li",null,"与位置外推分工：一个管锐度，一个管谁相容。"),t("li",null,"按行用因果可见长度比用全局 \\(n\\) 更一致。"),t("li",null,"出处：Chiang & Cholak, ICLR 2022；Press et al., ICLR 2022。")],-1))])}const q=s(c,[["render",f]]);export{S as __pageData,q as default};
